-- Mocks temporales. En producción se usan tablas reales, vistas adaptadoras o sinónimos.
CREATE TABLE ERP_PERSONA (PER_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NOMBRE VARCHAR2(150) NOT NULL);
CREATE TABLE ERP_EMPRESA (EMP_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NOMBRE VARCHAR2(150) NOT NULL);
CREATE TABLE ERP_SUCURSAL (SUC_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NOMBRE VARCHAR2(150) NOT NULL);
CREATE TABLE ERP_DEPARTAMENTO (DPT_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NOMBRE VARCHAR2(150) NOT NULL);
CREATE TABLE ERP_USUARIO (USU_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NOMBRE VARCHAR2(150) NOT NULL);
CREATE TABLE ERP_BANCO (BAN_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NOMBRE VARCHAR2(150) NOT NULL);
CREATE TABLE CXC_DTE (DTE_ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, NOMBRE VARCHAR2(150) NOT NULL);
